Ну и, наконец, самая общая (но и самая сложная) форма обменных операций —
на случай, если предыдущие не обеспечивают желаемое поведение в тонких дета-
лях:

#include <sys/socket.h>
/* Send a VLEN messages as described by VMESSAGES to socket FD.
   Returns the number of datagrams successfully written or -1 for errors.
   This function is a cancellation point and therefore not marked with
   __THROW.  */
extern int sendmmsg (int __fd, struct mmsghdr *__vmessages,
                     unsigned int __vlen, int __flags);
/* Receive a message as described by MESSAGE from socket FD.
   Returns the number of bytes read or -1 for errors.
  This function is a cancellation point and therefore not marked with
   __THROW.  */
extern ssize_t recvmsg (int __fd, struct msghdr *__message, int __flags);

Большинство аргументов этих функций скрыто в структуре:

#include <bits/socket.h>
/* Structure describing messages sent by `sendmsg' and received by `recvmsg'.  */
struct msghdr {
    void *msg_name;            /* Address to send to/receive from.  */
    socklen_t msg_namelen;      /* Length of address data.  */
    struct iovec *msg_iov;      /* Vector of data to send/receive into.  */
    size_t msg_iovlen;         /* Number of elements in the vector.  */
    void *msg_control;         /* Ancillary data (eg BSD filedesc passing). */
    size_t msg_controllen;      /* Ancillary data buffer length.
                                 !! The type should be socklen_t but the
                                   definition of the kernel is incompatible
                                  with this.  */
   int msg_flags;              /* Flags on received message.  */
  };

Параметры сокета

API сокетов включает ряд функций, дающих уточненную информацию о сокете
или управляющих особенностями поведения сокета. Вот важнейшая из этих воз-
можностей:

/* Put the current value for socket FD's option OPTNAME at protocol level LEVEL
   into OPTVAL (which is *OPTLEN bytes long), and set *OPTLEN to the value's
   actual length.  Returns 0 on success, -1 for errors.  */
extern int getsockopt(int __fd, int __level, int __optname,
                     void *__restrict __optval,
                      socklen_t *__restrict __optlen) __THROW;
/* Set socket FD's option OPTNAME at protocol level LEVEL
   to *OPTVAL (which is OPTLEN bytes long).
   Returns 0 on success, -1 for errors.  */
extern int setsockopt(int __fd, int __level, int __optname,
                      const void *__optval, socklen_t __optlen) __THROW;

Программирование сетевых приложений                                         149

extern int getpeername(int __fd, __SOCKADDR_ARG __addr,
                       socklen_t *__restrict __len) __THROW;

Первая из них (getsockname()) возвращает локальную, а вторая (getpeername()) — уда-
ленную адресную структуру протокола, связанную на текущий момент с сокетом.

Использование сокетного API

Базовые схемы построения обмена в клиентских и серверных кодах и для UDP,
и для TCP остаются практически постоянными от проекта к проекту, хотя в деталях
могут существенно различаться1. Рассмотрим эти базовые схемы (все примеры
кодов находятся в каталоге echo-cli-serv сопровождающего книгу файлового архива).

Общие определения:

 Файл common.h

