TCP клиент-сервер

Поскольку TCP — потоковый протокол, то полезно предварительно написать
функции записи в поток и чтения из потока (именно потому, что в TCP нет «паке-
тов» и размер чтения/записи за одну операцию может быть произвольным):

 Файл writen.c

#include "common.h"

/* Write "n" bytes to a descriptor */
ssize_t writen(int fd, const void *vptr, size_t n) {
   size_t nleft;

Программирование сетевых приложений                                         153

   ssize_t nwritten;
   nleft = n;
   while (nleft > 0) {
      if ((nwritten = write(fd, vptr, nleft)) <= 0) {
         if (errno == EINTR) nwritten = 0;     /* and call write() again */
         else return(-1);                    /* error */
     }
      nleft -= nwritten;
      vptr  += nwritten;
   }
   return(n);
}

