Для установки обработчика протоколов транспортного уровня существует API
<net/protocol.h>:

struct net_protocol {                // This is used to register protocols
   int  (*handler)(struct sk_buff *skb);
   void (*err_handler)(struct sk_buff *skb, u32 info);
   int  (*gso_send_check)(struct sk_buff *skb);
   struct sk_buff *(*gso_segment)(struct sk_buff *skb, int features);
   struct sk_buff **(*gro_receive)(struct sk_buff **head, struct sk_buff *skb);
   int (*gro_complete)(struct sk_buff *skb);
   unsigned int no_policy:1,
                netns_ok:1;
};
int inet_add_protocol(const struct net_protocol *prot, unsigned char num);
int inet_del_protocol(const struct net_protocol *prot, unsigned char num);

Здесь второй параметр вызова функций (num) как раз и есть константа из набора
констант вида IPPROTO_*.
Эта схема в общих чертах напоминает то, как это же делалось на сетевом уровне:
каждый пакет проходит через функцию-фильтр, где мы можем анализировать или
изменять отдельные поля сокетного буфера, отображающего пакет.

Вот пример модуля, устанавливающего протокол (см. каталог network/netproto со-
провождающего книгу файлового архива).

